css:
.sh__rule { display: block; width: 3.5rem; height: 3px; border-radius: 3px; background: linear-gradient(90deg, #6b8e36, #eec02b); margin-bottom: clamp(1.4rem, 3vw, 2.2rem); }
.sh__h { margin: 0; max-width: 18ch; }
.sh__lead { margin: 1.2rem 0 0; max-width: 24ch; font-family: var(--os-font-heading); font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2.15rem); line-height: 1.2; letter-spacing: -0.012em; color: var(--os-color-heading); }
